(window.BANKS = window.BANKS || []).push({"kode": "SIF001", "matkul": "Algoritma dan Pemrograman", "singkat": "AP", "warna": "#1f5fbf", "semester": 1, "uts": "P07", "genInfo": "hitungan dan penelusuran kode C++: operator dan modulus, increment, if-else, jumlah putaran loop, indeks array, bubble/selection sort, sequential search, dan fungsi rekursif", "catatan": "Soal disusun dari materi PDF, slide tatap maya, dan kisi-kisi ujian Algoritma dan Pemrograman.", "topics": [{"id": "P01", "judul": "Pengenalan Algoritma dan Pemrograman", "sumber": ["Materi 01 - Tatap Maya 1"], "ringkasan": ["Algoritma = urutan langkah logis dan terbatas untuk menyelesaikan masalah; ibarat resep.", "Nama 'algoritma' berasal dari ilmuwan Muslim Al-Khwarizmi.", "Alur kerja: masalah → algoritma (flowchart/pseudocode) → kode program → dijalankan komputer.", "Pseudocode: bahasa penengah manusia–komputer, mirip kode tapi tidak terikat sintaks bahasa tertentu.", "Flowchart (diagram alir): bagan dengan simbol grafis standar yang menggambarkan aliran algoritma.", "C++ bahasa yang dikompilasi: kode sumber diterjemahkan compiler menjadi bahasa mesin, sehingga program efisien.", "IDE = lingkungan pengembangan terintegrasi (editor + compiler + debugger dalam satu aplikasi)."], "tags": {"algoritma": "Pengertian algoritma", "notasi": "Pseudocode & flowchart", "kompilasi": "Compiler, IDE & bahasa mesin"}, "media": []}, {"id": "P02", "judul": "Bahasa C++: Struktur Program, Variabel, Tipe Data, I/O", "sumber": ["Materi 02 - Bahasa C++", "Pengenalan bahasa C++ (slide)"], "ringkasan": ["C++ = bahasa tingkat tinggi, pengembangan dari bahasa C, mendukung OOP, dan case sensitive (huruf besar ≠ kecil). File berekstensi .cpp.", "Bagian program: komentar (// atau /* */), identifier (nama buatan programmer), keyword (kata khusus, tak boleh jadi nama), library function.", "#include <iostream> = preprocessor directive yang memakai pustaka iostream (cout, cin).", "int main() = fungsi utama yang pertama dijalankan; { } membuka/menutup blok; setiap pernyataan diakhiri titik koma.", "cout << untuk output (insertion operator), cin >> untuk input (extraction operator).", "Variabel = nama lokasi penyimpanan di memori. Nama harus diawali huruf/garis bawah, tanpa spasi atau tanda minus, dan bukan keyword.", "Tipe data: int (bulat), float/double (pecahan), char (satu karakter), string (teks), bool (true/false).", "Ukuran umum: char 1 byte, short 2, int 4, float 4, double 8 byte."], "tags": {"struktur": "Struktur program C++", "variabel": "Variabel & aturan penamaan", "tipe": "Tipe data", "io": "Input/output cin & cout"}, "media": []}, {"id": "P03", "judul": "Operator, Struktur, dan Kontrol Statement", "sumber": ["Materi 03 - Operator", "Tatap Maya 2"], "ringkasan": ["Operator = simbol untuk memanipulasi data; operand = data yang dimanipulasi (pada A + B, A dan B operand, + operator).", "Sifat: unary (1 operand, mis. -a, ++), binary (2 operand, mis. a + b), ternary (3 operand: kondisi ? nilai1 : nilai2).", "Aritmetika: + - * / %. Pembagian dua int menghasilkan int (7/2 = 3); % = sisa bagi (7 % 2 = 1).", "Compound assignment: x += 3 sama dengan x = x + 3 (juga -=, *=, /=, %=).", "Increment/decrement: ++x (prefix) naik dulu baru dipakai; x++ (postfix) dipakai dulu baru naik.", "Relasional: == != < > <= >= menghasilkan true (1) atau false (0). Ingat: = adalah assignment, == perbandingan.", "Logika: && (dan), || (atau), ! (bukan).", "Operator koma: a = (b=3, b+2, c=10) → a bernilai ekspresi paling kanan (10)."], "tags": {"jenis": "Operand & sifat operator", "aritmetika": "Aritmetika & modulus", "inc": "Increment & compound", "relasi": "Relasional & logika", "ternary": "Ternary & koma"}, "media": []}, {"id": "P04", "judul": "Percabangan if dan if-else", "sumber": ["Materi 04 - Percabangan"], "ringkasan": ["Percabangan: pernyataan dijalankan hanya jika kondisi terpenuhi (atau tidak).", "if (kondisi) { ... } → blok jalan hanya jika kondisi true.", "if-else → satu blok untuk true, blok lain untuk false.", "if - else if - else → memilih satu dari banyak kemungkinan; kondisi diperiksa dari atas, berhenti di yang pertama true.", "Tanpa kurung kurawal, if hanya mengendalikan SATU pernyataan setelahnya.", "Contoh: nilai > 60 → 'Lulus'; bilangan < 0 → 'negatif', selain itu 'positif'."], "tags": {"if": "if tunggal", "ifelse": "if-else", "elseif": "if-else if bertingkat"}, "media": []}, {"id": "P05", "judul": "Percabangan Bersarang dan switch-case", "sumber": ["Materi 05 - Percabangan"], "ringkasan": ["If bersarang (nested if): if di dalam if, untuk kondisi yang bertingkat.", "switch (ekspresi) { case nilai: ...; break; default: ... } untuk pilihan bernilai pasti (int/char).", "break menghentikan switch; tanpa break eksekusi 'jatuh' (fall-through) ke case berikutnya.", "default dijalankan jika tidak ada case yang cocok (mirip else).", "switch tidak bisa menguji rentang (mis. nilai > 80); untuk rentang pakai if-else if."], "tags": {"nested": "If bersarang", "switch": "switch-case", "break": "break & default"}, "media": []}, {"id": "P06", "judul": "Perulangan for", "sumber": ["Materi 06 - Perulangan"], "ringkasan": ["Perulangan mengulang pernyataan n kali atau selama kondisi terpenuhi.", "Ciri perulangan: ada kondisi awal, syarat pengulangan, dan step (perubahan nilai).", "for (inisialisasi; kondisi; step) { ... } — cocok bila jumlah ulangan diketahui.", "Urutan: inisialisasi (sekali) → cek kondisi → jalankan blok → step → cek kondisi lagi.", "Inisialisasi dan step boleh dikosongkan, tapi titik koma tetap wajib: for(;n<10;).", "for (int i=0; i<n; i++) berulang n kali; for (int i=1; i<=n; i++) juga n kali."], "tags": {"konsep": "Konsep perulangan", "for": "Sintaks & cara kerja for", "trace": "Menelusuri output for"}, "media": []}, {"id": "P07", "judul": "Perulangan while dan do-while", "sumber": ["Materi 07 - Perulangan"], "ringkasan": ["while (kondisi) { ... } — kondisi dicek DULU; bisa 0 kali berjalan.", "do { ... } while (kondisi); — blok dijalankan dulu, kondisi dicek di akhir; minimal 1 kali.", "Perlu step (mis. n--) agar suatu saat kondisi false; tanpa itu terjadi infinite loop.", "Contoh countdown: n=5, while(n>0){cout<<n; n--;} → 54321.", "Loop bersarang: loop dalam berjalan penuh untuk setiap putaran loop luar (total = luar × dalam)."], "tags": {"while": "while", "dowhile": "do-while", "nested": "Loop bersarang & infinite loop"}, "media": []}, {"id": "P09", "judul": "Tipe Data Larik (Array)", "sumber": ["Materi 09 - Array", "Tatap Maya 5"], "ringkasan": ["Array = kumpulan elemen bertipe SAMA dengan satu nama, diakses lewat indeks.", "Deklarasi: int a[5]; → 5 elemen, indeks 0 sampai 4.", "Inisialisasi: int a[4] = {2,4,6,8}; → a[0]=2, a[3]=8.", "Indeks tidak boleh melebihi batas: int larik[10] → indeks terakhir 9; larik[10] salah.", "Ukuran memori = ukuran tipe × jumlah elemen (short 2 byte × 5 = 10 byte).", "Array tidak bisa disalin langsung (a = b salah); salin per elemen dengan for."], "tags": {"konsep": "Konsep & deklarasi array", "indeks": "Indeks & akses elemen", "olah": "Mengolah array dengan loop"}, "media": []}, {"id": "P10", "judul": "Struct C++", "sumber": ["Materi 10 - Struct", "Tatap Maya 6"], "ringkasan": ["struct mengelompokkan beberapa variabel BERBEDA tipe menjadi satu tipe data baru (record).", "Bentuk: struct Produk { string nama; float harga; }; — ingat titik koma setelah }.", "Variabel di dalam struct disebut member/field.", "Struct hanyalah rancangan; harus dibuat object dulu (Produk p;) sebelum member dipakai.", "Akses member dengan operator titik: p.nama, p.harga.", "Struct bisa dijadikan array: Mahasiswa mhs[30]; mhs[0].nim."], "tags": {"konsep": "Konsep & deklarasi struct", "akses": "Object & akses member", "array": "Array of struct"}, "media": []}, {"id": "P11", "judul": "Function: Dasar dan Deklarasi", "sumber": ["Materi 11 - Fungsi"], "ringkasan": ["Fungsi = bagian program terpisah untuk tugas tertentu; minimal ada main().", "Keuntungan: struktur jelas (readability) dan bisa dipakai ulang (reusability).", "Jenis: fungsi pustaka (sqrt, pow, strlen, toupper…) dan fungsi buatan programmer.", "Bentuk: tipe nama(parameter) { pernyataan; return nilai; }", "Prototype (deklarasi) ditulis sebelum main jika definisi fungsi diletakkan setelah main.", "Fungsi void tidak mengembalikan nilai."], "tags": {"konsep": "Konsep & manfaat fungsi", "pustaka": "Fungsi pustaka", "deklarasi": "Deklarasi, prototype & void"}, "media": []}, {"id": "P12", "judul": "Function: Parameter dan Nilai Balik", "sumber": ["Materi 12 - Subprogram dan Fungsi"], "ringkasan": ["Parameter formal = di definisi fungsi; argumen/parameter aktual = nilai saat memanggil.", "return mengirim nilai balik ke pemanggil dan menghentikan fungsi.", "Pass by value: fungsi menerima salinan; perubahan tidak memengaruhi variabel asli.", "Pass by reference (int &x): fungsi bekerja pada variabel asli; perubahan terbawa keluar.", "Rekursif: fungsi memanggil dirinya sendiri; wajib punya base case agar berhenti (mis. faktorial)."], "tags": {"parameter": "Parameter & argumen", "return": "Nilai balik return", "referensi": "By value vs by reference", "rekursif": "Fungsi rekursif"}, "media": []}, {"id": "P13", "judul": "Sorting (Pengurutan)", "sumber": ["Materi 13 - Sorting"], "ringkasan": ["Algoritma (Levitin): urutan instruksi jelas untuk memperoleh output dari input yang sah dalam waktu terbatas.", "Brute force = pendekatan langsung/sederhana; contohnya bubble sort dan selection sort.", "Selection sort: cari elemen terkecil dari bagian belum urut, tukar ke posisi depan bagian itu; ulangi.", "Bubble sort: bandingkan pasangan bersebelahan dan tukar jika salah urutan; elemen terbesar 'menggelembung' ke akhir setiap putaran.", "Untuk n elemen, keduanya butuh n-1 putaran luar.", "Contoh algoritma lain: FPB Euclid — while n≠0: r = m mod n; m = n; n = r; hasil m."], "tags": {"konsep": "Algoritma & brute force", "selection": "Selection sort", "bubble": "Bubble sort"}, "media": []}, {"id": "P14", "judul": "Konsep dan Algoritma Sequential Search", "sumber": ["Materi 14 - Sequential Search"], "ringkasan": ["Sequential (linear) search = pencarian brute force: bandingkan kunci K dengan elemen dari awal sampai akhir.", "Berhenti begitu kunci ditemukan; tidak perlu membandingkan sisa elemen.", "Pseudocode: i←0; while i<n and A[i]≠K do i←i+1; if i<n return i else return -1.", "Output: indeks pertama yang cocok, atau -1 jika tidak ada.", "Tidak memerlukan data terurut."], "tags": {"konsep": "Konsep sequential search", "trace": "Menelusuri hasil pencarian"}, "media": []}, {"id": "P15", "judul": "Implementasi dan Variasi Sequential Search", "sumber": ["Materi 15 - Sequential Search"], "ringkasan": ["Implementasi C++: for (i=0; i<n; i++) if (A[i]==K) return i; return -1;", "Sentinel: tambahkan K di posisi A[n] sebagai elemen fiktif sehingga loop pasti berhenti tanpa cek i<n.", "Setelah loop sentinel: jika i<n ketemu di indeks i; jika i==n berarti tidak ada (hanya ketemu sentinel).", "Variasi mencari SEMUA kemunculan: jangan berhenti saat ketemu, catat/hitung setiap indeks yang cocok.", "Jumlah perbandingan terburuk = n (kunci di akhir atau tidak ada)."], "tags": {"cpp": "Implementasi di C++", "sentinel": "Teknik sentinel", "semua": "Mencari semua kemunculan"}, "media": []}], "questions": [{"p": "P01", "tag": "algoritma", "type": "mcq", "q": "Pengertian algoritma yang paling tepat adalah…", "opts": ["Urutan langkah logis dan terbatas untuk menyelesaikan masalah", "Bahasa pemrograman tingkat tinggi", "Perangkat keras untuk menjalankan program", "Kumpulan data yang disimpan di memori", "Program yang menerjemahkan kode ke bahasa mesin"], "ans": 0, "why": "Algoritma adalah langkah-langkah logis, sistematis, dan terbatas untuk menyelesaikan masalah; ia inti dari pemrograman.", "lvl": 1, "code": null, "src": "modul", "id": "P01-001"}, {"p": "P01", "tag": "algoritma", "type": "mcq", "q": "Istilah algoritma berasal dari nama tokoh…", "opts": ["Al-Khwarizmi", "Al-Ghazali", "Ibnu Sina", "Alan Turing", "Charles Babbage"], "ans": 0, "why": "Materi menyebut algoritma berasal dari nama Al-Khwarizmi, matematikawan Muslim.", "lvl": 1, "code": null, "src": "modul", "id": "P01-002"}, {"p": "P01", "tag": "algoritma", "type": "mcq", "q": "Materi mengibaratkan algoritma seperti…", "opts": ["Resep masakan", "Kamus", "Peta jalan tanpa tujuan", "Kalkulator", "Buku harian"], "ans": 0, "why": "Resep memberi tahu cara menyelesaikan tugas lewat sejumlah langkah — persis seperti algoritma.", "lvl": 1, "code": null, "src": "modul", "id": "P01-003"}, {"p": "P01", "tag": "algoritma", "type": "mcq", "q": "Mana yang BUKAN ciri algoritma yang baik?", "opts": ["Langkahnya boleh ambigu asal hasilnya benar", "Setiap langkah jelas", "Jumlah langkah terbatas", "Ada input dan output", "Logis dan berurutan"], "ans": 0, "why": "Setiap langkah algoritma harus jelas (nonambiguity) dan terbatas; langkah ambigu tidak bisa dijalankan pasti oleh komputer.", "lvl": 1, "code": null, "src": "modul", "id": "P01-004"}, {"p": "P01", "tag": "algoritma", "type": "mcq", "q": "Urutan yang benar dari masalah sampai program berjalan adalah…", "opts": ["Masalah → algoritma (flowchart/pseudocode) → kode program → dijalankan", "Kode program → masalah → algoritma → dijalankan", "Algoritma → kode → masalah → flowchart", "Flowchart → masalah → kode → algoritma", "Dijalankan → kode → algoritma → masalah"], "ans": 0, "why": "Kisi-kisi CPMK 01: alur dari masalah, dirancang dengan flowchart atau pseudocode, lalu ditulis sebagai kode program.", "lvl": 1, "code": null, "src": "modul", "id": "P01-005"}, {"p": "P01", "tag": "notasi", "type": "mcq", "q": "Pseudocode adalah…", "opts": ["Deskripsi algoritma mirip kode yang ditujukan untuk dibaca manusia, tidak terikat sintaks bahasa tertentu", "Kode mesin dalam bentuk biner", "Diagram dengan simbol grafis standar", "Bahasa yang langsung dieksekusi CPU", "Kumpulan komentar dalam program"], "ans": 0, "why": "Pseudocode adalah bahasa penengah manusia–komputer; memakai konvensi struktur bahasa pemrograman tetapi untuk dibaca manusia, bukan mesin.", "lvl": 1, "code": null, "src": "modul", "id": "P01-006"}, {"p": "P01", "tag": "notasi", "type": "mcq", "q": "Bagan dengan simbol-simbol grafis yang menyatakan aliran algoritma disebut…", "opts": ["Flowchart", "Pseudocode", "Source code", "Compiler", "Header file"], "ans": 0, "why": "Flowchart (diagram alir) memakai simbol grafis untuk menggambarkan aliran algoritma secara detail.", "lvl": 1, "code": null, "src": "modul", "id": "P01-007"}, {"p": "P01", "tag": "notasi", "type": "mcq", "q": "Mengapa pseudocode tidak memuat detail seperti deklarasi variabel?", "opts": ["Tujuannya memudahkan manusia memahami algoritma, jadi detail yang tidak perlu dihilangkan", "Karena komputer tidak membutuhkan variabel", "Karena pseudocode hanya untuk bahasa C++", "Karena deklarasi variabel dilarang dalam algoritma", "Agar bisa langsung dikompilasi"], "ans": 0, "why": "Materi: pseudocode meninggalkan detail seperti deklarasi variabel karena tujuannya agar mudah dipahami manusia dan tidak bergantung sistem tertentu.", "lvl": 1, "code": null, "src": "modul", "id": "P01-008"}, {"p": "P01", "tag": "notasi", "type": "mcq", "q": "Simbol flowchart berbentuk belah ketupat (diamond) dipakai untuk…", "opts": ["Keputusan/percabangan (ya/tidak)", "Mulai dan selesai", "Input/output", "Proses perhitungan", "Arah aliran"], "ans": 0, "why": "Simbol decision (belah ketupat) menandai titik keputusan dengan cabang ya/tidak.", "lvl": 2, "code": null, "src": "modul", "id": "P01-009"}, {"p": "P01", "tag": "notasi", "type": "mcq", "q": "Simbol flowchart berbentuk jajar genjang menyatakan…", "opts": ["Input atau output data", "Keputusan", "Mulai/selesai", "Proses", "Penghubung antar halaman"], "ans": 0, "why": "Jajar genjang dipakai untuk operasi input/output, misalnya membaca nilai atau menampilkan hasil.", "lvl": 2, "code": null, "src": "modul", "id": "P01-010"}, {"p": "P01", "tag": "kompilasi", "type": "mcq", "q": "Program yang menerjemahkan seluruh kode sumber C++ menjadi bahasa mesin disebut…", "opts": ["Compiler", "Editor teks", "Flowchart", "Pseudocode", "Browser"], "ans": 0, "why": "C++ adalah bahasa yang dikompilasi: compiler menerjemahkan kode sumber menjadi bahasa mesin sehingga program efisien.", "lvl": 1, "code": null, "src": "modul", "id": "P01-011"}, {"p": "P01", "tag": "kompilasi", "type": "mcq", "q": "Mengapa kode bahasa tingkat tinggi perlu diterjemahkan?", "opts": ["Komputer hanya memahami bahasa mesin", "Agar kode lebih panjang", "Agar bisa dibaca manusia", "Karena IDE memintanya", "Supaya tidak perlu algoritma"], "ans": 0, "why": "Komputer hanya memahami bahasa mesin, sedangkan manusia menulis dalam bahasa tingkat tinggi — maka perlu compiler/interpreter/assembler.", "lvl": 1, "code": null, "src": "modul", "id": "P01-012"}, {"p": "P01", "tag": "kompilasi", "type": "mcq", "q": "IDE (Integrated Development Environment) adalah…", "opts": ["Aplikasi yang menyatukan editor, compiler, dan alat developer lain dalam satu antarmuka", "Jenis tipe data", "Bahasa mesin", "Simbol flowchart", "Sistem operasi"], "ans": 0, "why": "IDE menyediakan antarmuka pusat untuk alat developer sehingga pengembangan lebih efisien; contoh Dev-C++, Geany.", "lvl": 1, "code": null, "src": "modul", "id": "P01-013"}, {"p": "P01", "tag": "kompilasi", "type": "mcq", "q": "Kumpulan alat untuk membangun program C++ yang intinya adalah compiler disebut…", "opts": ["Development toolchain", "Flowchart", "Pseudocode", "Header", "Library function"], "ans": 0, "why": "Materi: C++ butuh seperangkat alat bernama development toolchain, intinya compiler.", "lvl": 2, "code": null, "src": "modul", "id": "P01-014"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Pernyataan yang benar tentang C++ adalah…", "opts": ["Case sensitive: Nilai dan nilai dianggap berbeda", "Tidak membedakan huruf besar dan kecil", "Bahasa tingkat rendah", "Tidak mendukung OOP", "Berkas sumbernya berekstensi .py"], "ans": 0, "why": "C++ case sensitive, bahasa tingkat tinggi pengembangan dari C, mendukung OOP, dan file sumbernya .cpp.", "lvl": 1, "code": null, "src": "modul", "id": "P02-001"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "#include <iostream> disebut…", "opts": ["Preprocessor directive", "Komentar", "Fungsi utama", "Variabel global", "Keyword"], "ans": 0, "why": "Baris yang diawali # adalah preprocessor directive; #include <iostream> menyertakan pustaka iostream (cout, cin).", "lvl": 1, "code": null, "src": "modul", "id": "P02-002"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Fungsi yang pertama kali dijalankan secara otomatis dalam program C++ adalah…", "opts": ["main()", "cout()", "include()", "start()", "iostream()"], "ans": 0, "why": "int main() adalah fungsi utama yang otomatis dibaca kompilator pertama kali.", "lvl": 1, "code": null, "src": "modul", "id": "P02-003"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Cara menulis komentar di C++ adalah…", "opts": ["// komentar  atau  /* komentar */", "# komentar", "<!-- komentar -->", "-- komentar", "' komentar"], "ans": 0, "why": "C++ mengenal komentar satu baris // dan komentar blok /* ... */; komentar tidak dieksekusi.", "lvl": 1, "code": null, "src": "modul", "id": "P02-004"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Setiap pernyataan (statement) di C++ diakhiri dengan…", "opts": ["Titik koma ;", "Titik .", "Titik dua :", "Koma ,", "Kurung tutup )"], "ans": 0, "why": "Deklarasi dan pernyataan di C++ diakhiri tanda titik koma.", "lvl": 1, "code": null, "src": "modul", "id": "P02-005"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Kata seperti class, new, delete, dan public yang punya arti khusus dan tidak boleh jadi nama variabel disebut…", "opts": ["Keyword", "Identifier", "Library function", "Komentar", "Operand"], "ans": 0, "why": "Keyword adalah kata khusus bahasa; tidak boleh dipakai sebagai identifier.", "lvl": 1, "code": null, "src": "modul", "id": "P02-006"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Nama yang diberikan programmer untuk variabel, fungsi, atau konstanta disebut…", "opts": ["Identifier", "Keyword", "Preprocessor", "Header", "Statement"], "ans": 0, "why": "Identifier adalah nama buatan programmer untuk program, fungsi, variabel, konstanta, dan lain-lain.", "lvl": 1, "code": null, "src": "modul", "id": "P02-007"}, {"p": "P02", "tag": "struktur", "type": "mcq", "q": "Tanda { dan } dalam fungsi main berfungsi sebagai…", "opts": ["Pembuka dan penutup blok (ruang lingkup) kode", "Komentar", "Operator perbandingan", "Penanda string", "Pemisah parameter"], "ans": 0, "why": "Kurung kurawal mengapit blok kode yang menjadi satu scope, misalnya isi fungsi main.", "lvl": 1, "code": null, "src": "modul", "id": "P02-008"}, {"p": "P02", "tag": "variabel", "type": "mcq", "q": "Variabel adalah…", "opts": ["Nama lokasi penyimpanan di memori yang nilainya dapat berubah", "Nilai tetap yang tidak bisa diubah", "Perintah untuk mencetak", "Jenis operator", "Nama file program"], "ans": 0, "why": "Variabel mewakili alamat memori tempat menyimpan nilai; nilainya bisa berubah selama program berjalan.", "lvl": 1, "code": null, "src": "modul", "id": "P02-009"}, {"p": "P02", "tag": "variabel", "type": "mcq", "q": "Nama variabel berikut yang VALID adalah…", "opts": ["Keliling_Lingkaran", "1X", "luas-1", "Keliling Lingkaran", "float"], "ans": 0, "why": "Nama harus diawali huruf/garis bawah, tanpa spasi atau tanda minus, dan bukan keyword. Keliling_Lingkaran memenuhi semua aturan.", "lvl": 1, "code": null, "src": "modul", "id": "P02-010"}, {"p": "P02", "tag": "variabel", "type": "mcq", "q": "Mengapa 'luas-1' tidak boleh dipakai sebagai nama variabel?", "opts": ["Mengandung tanda minus", "Terlalu pendek", "Diawali huruf kecil", "Mengandung angka di akhir", "Merupakan keyword"], "ans": 0, "why": "Tanda minus dibaca sebagai operator pengurangan, sehingga dilarang dalam nama variabel.", "lvl": 1, "code": null, "src": "modul", "id": "P02-011"}, {"p": "P02", "tag": "variabel", "type": "mcq", "q": "Memberi nilai langsung saat deklarasi, misalnya int umur = 20; disebut…", "opts": ["Inisialisasi", "Iterasi", "Kompilasi", "Deklarasi fungsi", "Casting"], "ans": 0, "why": "Pemberian nilai saat deklarasi variabel disebut inisialisasi.", "lvl": 1, "code": null, "src": "modul", "id": "P02-012"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "Tipe data yang tepat untuk menyimpan nilai 3.75 adalah…", "opts": ["float atau double", "int", "char", "bool", "void"], "ans": 0, "why": "Bilangan pecahan disimpan di float (presisi tunggal) atau double (presisi ganda).", "lvl": 1, "code": null, "src": "modul", "id": "P02-013"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "Tipe data yang hanya bisa bernilai true atau false adalah…", "opts": ["bool", "int", "char", "string", "float"], "ans": 0, "why": "bool mewakili satu dari dua nilai: true (1) atau false (0).", "lvl": 1, "code": null, "src": "modul", "id": "P02-014"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "char berbeda dengan string karena…", "opts": ["char menyimpan satu karakter, string menyimpan kumpulan karakter", "char untuk angka, string untuk huruf", "char lebih besar dari string", "string hanya satu huruf", "Keduanya sama"], "ans": 0, "why": "char = karakter tunggal (mis. 'A'); string = kumpulan karakter (mis. \"pekerti\").", "lvl": 1, "code": null, "src": "modul", "id": "P02-015"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "Berdasarkan contoh sizeof di materi, ukuran tipe double adalah…", "opts": ["8 byte", "1 byte", "2 byte", "4 byte", "16 byte"], "ans": 0, "why": "Output contoh: char 1, short 2, int 4, float 4, double 8 byte.", "lvl": 2, "code": null, "src": "modul", "id": "P02-016"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "Berdasarkan contoh sizeof di materi, ukuran tipe int adalah…", "opts": ["4 byte", "1 byte", "2 byte", "8 byte", "16 byte"], "ans": 0, "why": "Pada contoh output, sizeof(int) = 4.", "lvl": 2, "code": null, "src": "modul", "id": "P02-017"}, {"p": "P02", "tag": "tipe", "type": "mcq", "q": "Deklarasi yang benar untuk menyimpan nama mahasiswa adalah…", "opts": ["string nama = \"Didi\";", "int nama = \"Didi\";", "char nama = \"Didi\";", "bool nama = \"Didi\";", "float nama = Didi;"], "ans": 0, "why": "Teks (kumpulan karakter) disimpan dalam tipe string dengan tanda petik dua.", "lvl": 1, "code": null, "src": "modul", "id": "P02-018"}, {"p": "P02", "tag": "io", "type": "mcq", "q": "Perintah C++ untuk menampilkan output ke layar adalah…", "opts": ["cout", "cin", "printf saja", "scanf", "input"], "ans": 0, "why": "cout adalah object output dari iostream, dipakai dengan insertion operator <<.", "lvl": 1, "code": null, "src": "modul", "id": "P02-019"}, {"p": "P02", "tag": "io", "type": "mcq", "q": "Operator yang dipakai bersama cin adalah…", "opts": [">> (extraction operator)", "<< (insertion operator)", "==", "->", "::"], "ans": 0, "why": "cin memakai extraction operator >> untuk mengambil input ke variabel: cin >> umur;", "lvl": 1, "code": null, "src": "modul", "id": "P02-020"}, {"p": "P02", "tag": "io", "type": "mcq", "q": "Operator << pada cout disebut…", "opts": ["Insertion operator", "Extraction operator", "Scope operator", "Shift-right", "Ternary"], "ans": 0, "why": "cout << \"teks\" memakai insertion operator <<.", "lvl": 1, "code": null, "src": "modul", "id": "P02-021"}, {"p": "P02", "tag": "io", "type": "mcq", "q": "Output program berikut adalah…", "opts": ["Halo 20", "Halo umur", "Halo\n20", "20 Halo", "Error"], "ans": 0, "why": "cout mencetak teks \"Halo \" lalu nilai variabel umur (20) dalam satu baris.", "lvl": 2, "code": "int umur = 20;\ncout << \"Halo \" << umur;", "src": "modul", "id": "P02-022"}, {"p": "P03", "tag": "jenis", "type": "mcq", "q": "Pada ekspresi A + B, yang disebut operand adalah…", "opts": ["A dan B", "+", "A + B", "Hanya A", "Hanya B"], "ans": 0, "why": "Operand adalah data yang dimanipulasi (A dan B); operator adalah simbolnya (+).", "lvl": 1, "code": null, "src": "modul", "id": "P03-001"}, {"p": "P03", "tag": "jenis", "type": "mcq", "q": "Operator yang hanya melibatkan satu operand disebut…", "opts": ["Unary", "Binary", "Ternary", "Relasional", "Bitwise"], "ans": 0, "why": "Unary memakai satu operand, contohnya -a, ++x, x--.", "lvl": 1, "code": null, "src": "modul", "id": "P03-002"}, {"p": "P03", "tag": "jenis", "type": "mcq", "q": "Operator kondisi  ekspresi ? nilai1 : nilai2  termasuk operator…", "opts": ["Ternary", "Unary", "Binary", "Bitwise", "Compound"], "ans": 0, "why": "Conditional operator melibatkan tiga operand, sehingga disebut ternary.", "lvl": 1, "code": null, "src": "modul", "id": "P03-003"}, {"p": "P03", "tag": "jenis", "type": "mcq", "q": "a * b termasuk operator bersifat…", "opts": ["Binary", "Unary", "Ternary", "Logika", "Koma"], "ans": 0, "why": "Operator aritmetika melibatkan dua operand dengan operator di tengah — binary.", "lvl": 1, "code": null, "src": "modul", "id": "P03-004"}, {"p": "P03", "tag": "aritmetika", "type": "mcq", "q": "Hasil dari 17 % 5 adalah…", "opts": ["2", "3", "3.4", "5", "12"], "ans": 0, "why": "% adalah sisa bagi: 17 = 3×5 + 2, sisanya 2.", "lvl": 1, "code": null, "src": "modul", "id": "P03-005"}, {"p": "P03", "tag": "aritmetika", "type": "mcq", "q": "Jika a dan b bertipe int dengan a = 7, b = 2, maka a / b bernilai…", "opts": ["3", "3.5", "4", "1", "2"], "ans": 0, "why": "Pembagian dua int di C++ membuang bagian pecahan, jadi 7/2 = 3.", "lvl": 2, "code": null, "src": "modul", "id": "P03-006"}, {"p": "P03", "tag": "aritmetika", "type": "mcq", "q": "Untuk mengecek apakah bilangan x genap, kondisi yang tepat adalah…", "opts": ["x % 2 == 0", "x / 2 == 0", "x % 2 == 1", "x * 2 == 0", "x == 2"], "ans": 0, "why": "Bilangan genap habis dibagi 2, sehingga sisa baginya 0.", "lvl": 1, "code": null, "src": "modul", "id": "P03-007"}, {"p": "P03", "tag": "aritmetika", "type": "mcq", "q": "Nilai dari 2 + 3 * 4 di C++ adalah…", "opts": ["14", "20", "24", "9", "11"], "ans": 0, "why": "Perkalian dikerjakan lebih dulu: 3*4 = 12, lalu 2 + 12 = 14.", "lvl": 2, "code": null, "src": "modul", "id": "P03-008"}, {"p": "P03", "tag": "inc", "type": "mcq", "q": "x += 5 setara dengan…", "opts": ["x = x + 5", "x = 5", "x == x + 5", "x = x * 5", "x + 5 = x"], "ans": 0, "why": "Compound assignment += adalah bentuk singkat dari x = x + 5.", "lvl": 1, "code": null, "src": "modul", "id": "P03-009"}, {"p": "P03", "tag": "inc", "type": "mcq", "q": "Perbedaan ++x dan x++ adalah…", "opts": ["++x menaikkan dulu baru dipakai, x++ dipakai dulu baru dinaikkan", "Tidak ada beda sama sekali", "++x mengurangi 1", "x++ menaikkan 2", "++x hanya untuk float"], "ans": 0, "why": "Prefix (++x) dinaikkan sebelum diproses; postfix (x++) diproses dahulu sebelum dinaikkan.", "lvl": 1, "code": null, "src": "modul", "id": "P03-010"}, {"p": "P03", "tag": "inc", "type": "mcq", "q": "Setelah kode dijalankan, nilai a dan x adalah…", "opts": ["a = 5, x = 6", "a = 6, x = 6", "a = 5, x = 5", "a = 6, x = 5", "a = 7, x = 6"], "ans": 0, "why": "x++ adalah postfix: a menerima nilai lama (5), baru kemudian x naik menjadi 6.", "lvl": 2, "code": "int x = 5;\nint a = x++;", "src": "modul", "id": "P03-011"}, {"p": "P03", "tag": "inc", "type": "mcq", "q": "Setelah kode dijalankan, nilai a dan x adalah…", "opts": ["a = 6, x = 6", "a = 5, x = 6", "a = 5, x = 5", "a = 6, x = 5", "a = 7, x = 7"], "ans": 0, "why": "++x adalah prefix: x naik dulu jadi 6, lalu nilainya (6) diberikan ke a.", "lvl": 2, "code": "int x = 5;\nint a = ++x;", "src": "modul", "id": "P03-012"}, {"p": "P03", "tag": "inc", "type": "mcq", "q": "Nilai y setelah kode berikut adalah…", "opts": ["7", "10", "3", "13", "0"], "ans": 0, "why": "y -= 3 berarti y = y - 3 = 10 - 3 = 7.", "lvl": 1, "code": "int y = 10;\ny -= 3;", "src": "modul", "id": "P03-013"}, {"p": "P03", "tag": "relasi", "type": "mcq", "q": "Operator untuk memeriksa apakah dua nilai SAMA adalah…", "opts": ["==", "=", "!=", "=>", "==="], "ans": 0, "why": "== adalah operator perbandingan; = adalah assignment (pemberian nilai).", "lvl": 1, "code": null, "src": "modul", "id": "P03-014"}, {"p": "P03", "tag": "relasi", "type": "mcq", "q": "Hasil dari (5 > 3) && (2 > 4) adalah…", "opts": ["false (0)", "true (1)", "5", "Error", "2"], "ans": 0, "why": "&& bernilai true hanya jika kedua sisi true; 2 > 4 false, sehingga hasilnya false.", "lvl": 1, "code": null, "src": "modul", "id": "P03-015"}, {"p": "P03", "tag": "relasi", "type": "mcq", "q": "Hasil dari (5 > 3) || (2 > 4) adalah…", "opts": ["true (1)", "false (0)", "3", "Error", "4"], "ans": 0, "why": "|| bernilai true bila salah satu sisi true; 5 > 3 true.", "lvl": 1, "code": null, "src": "modul", "id": "P03-016"}, {"p": "P03", "tag": "relasi", "type": "mcq", "q": "Operator != berarti…", "opts": ["Tidak sama dengan", "Sama dengan", "Lebih dari atau sama dengan", "Bukan (negasi) saja", "Assignment"], "ans": 0, "why": "!= menghasilkan true jika kedua nilai berbeda.", "lvl": 1, "code": null, "src": "modul", "id": "P03-017"}, {"p": "P03", "tag": "relasi", "type": "mcq", "q": "Hasil operasi relasional di C++ berupa…", "opts": ["Nilai boolean: true (1) atau false (0)", "Bilangan pecahan", "String", "Karakter", "Alamat memori"], "ans": 0, "why": "Operator relasional dan perbandingan menghasilkan nilai boolean.", "lvl": 1, "code": null, "src": "modul", "id": "P03-018"}, {"p": "P03", "tag": "ternary", "type": "mcq", "q": "Nilai hasil setelah kode berikut adalah…", "opts": ["\"Lulus\"", "\"Gagal\"", "70", "true", "Error"], "ans": 0, "why": "Kondisi nilai >= 60 benar (70), sehingga ternary memilih nilai pertama: \"Lulus\".", "lvl": 2, "code": "int nilai = 70;\nstring hasil = (nilai >= 60) ? \"Lulus\" : \"Gagal\";", "src": "modul", "id": "P03-019"}, {"p": "P03", "tag": "ternary", "type": "mcq", "q": "Pada a = (b=3, b+2, c=10); nilai akhir a adalah…", "opts": ["10", "3", "5", "15", "0"], "ans": 0, "why": "Operator koma mengevaluasi semua ekspresi tetapi hanya yang paling kanan yang dipakai, jadi a = 10.", "lvl": 3, "code": null, "src": "modul", "id": "P03-020"}, {"p": "P04", "tag": "if", "type": "mcq", "q": "Percabangan dalam pemrograman adalah…", "opts": ["Pernyataan yang dieksekusi hanya jika suatu kondisi terpenuhi atau tidak", "Pengulangan pernyataan beberapa kali", "Penyimpanan banyak data dalam satu nama", "Pemanggilan fungsi lain", "Penerjemahan kode ke bahasa mesin"], "ans": 0, "why": "Materi: percabangan memungkinkan pernyataan dieksekusi hanya jika kondisi terpenuhi atau tidak terpenuhi.", "lvl": 1, "code": null, "src": "modul", "id": "P04-001"}, {"p": "P04", "tag": "if", "type": "mcq", "q": "Kalimat 'Jika hari hujan, maka saya membawa payung' paling tepat diterjemahkan dengan…", "opts": ["if", "if-else", "switch", "for", "while"], "ans": 0, "why": "Hanya ada satu aksi untuk satu kondisi tanpa alternatif, jadi cukup if tunggal.", "lvl": 1, "code": null, "src": "modul", "id": "P04-002"}, {"p": "P04", "tag": "if", "type": "mcq", "q": "Output kode berikut jika a = 50 adalah…", "opts": ["Tidak tampil apa-apa", "Lulus", "Tidak lulus", "50", "Error"], "ans": 0, "why": "Kondisi a > 60 bernilai false untuk 50 dan tidak ada else, sehingga tidak ada output.", "lvl": 2, "code": "if (a > 60)\n    cout << \"Lulus\";", "src": "modul", "id": "P04-003"}, {"p": "P04", "tag": "if", "type": "mcq", "q": "Tanpa tanda { }, sebuah if hanya mengendalikan…", "opts": ["Satu pernyataan tepat setelahnya", "Semua pernyataan sampai akhir main", "Dua pernyataan", "Seluruh fungsi", "Tidak ada pernyataan"], "ans": 0, "why": "Tanpa blok kurung kurawal, hanya satu statement setelah if yang terikat kondisi.", "lvl": 2, "code": null, "src": "modul", "id": "P04-004"}, {"p": "P04", "tag": "if", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["BC", "ABC", "C", "AC", "B"], "ans": 0, "why": "x > 10 false, jadi cout \"A\" dilewati. Tanpa kurung kurawal, cout \"B\" bukan bagian if sehingga tetap jalan, lalu \"C\".", "lvl": 3, "code": "int x = 5;\nif (x > 10)\n    cout << \"A\";\ncout << \"B\";\ncout << \"C\";", "src": "modul", "id": "P04-005"}, {"p": "P04", "tag": "ifelse", "type": "mcq", "q": "Pernyataan if-else digunakan ketika…", "opts": ["Ada satu aksi untuk kondisi true dan aksi lain untuk kondisi false", "Hanya ada satu aksi", "Ada banyak nilai pasti", "Perlu mengulang aksi", "Tidak ada kondisi"], "ans": 0, "why": "if-else menjalankan blok pertama jika true dan blok else jika false.", "lvl": 1, "code": null, "src": "modul", "id": "P04-006"}, {"p": "P04", "tag": "ifelse", "type": "mcq", "q": "Output kode berikut untuk bilangan = -1 adalah…", "opts": ["negatif", "positif", "-1", "nol", "Tidak ada output"], "ans": 0, "why": "-1 < 0 bernilai true, sehingga blok if dijalankan.", "lvl": 1, "code": "if (bilangan < 0)\n    cout << \"negatif\";\nelse\n    cout << \"positif\";", "src": "modul", "id": "P04-007"}, {"p": "P04", "tag": "ifelse", "type": "mcq", "q": "Pada kode bilangan positif/negatif, input 0 akan menghasilkan…", "opts": ["positif", "negatif", "nol", "Error", "Tidak ada output"], "ans": 0, "why": "0 < 0 false, maka masuk else yang mencetak \"positif\" — contoh pentingnya memeriksa kasus batas.", "lvl": 3, "code": "if (bilangan < 0)\n    cout << \"negatif\";\nelse\n    cout << \"positif\";", "src": "modul", "id": "P04-008"}, {"p": "P04", "tag": "ifelse", "type": "mcq", "q": "Kesalahan pada kode if (x = 5) adalah…", "opts": ["Memakai = (assignment), seharusnya == untuk membandingkan", "Seharusnya memakai :", "Seharusnya tanpa kurung", "Tidak ada kesalahan", "Harus memakai switch"], "ans": 0, "why": "x = 5 memberi nilai, bukan membandingkan; untuk menguji kesamaan gunakan ==.", "lvl": 2, "code": null, "src": "modul", "id": "P04-009"}, {"p": "P04", "tag": "elseif", "type": "mcq", "q": "Struktur if - else if - else digunakan untuk…", "opts": ["Memilih satu dari lebih dari dua kemungkinan", "Mengulang pernyataan", "Menyimpan data", "Membuat fungsi", "Hanya dua kemungkinan"], "ans": 0, "why": "Klausa else dapat berisi if-else lain sehingga bisa memilih dari banyak kemungkinan.", "lvl": 1, "code": null, "src": "modul", "id": "P04-010"}, {"p": "P04", "tag": "elseif", "type": "mcq", "q": "Output kode berikut untuk ipk = 2.7 adalah…", "opts": ["Puasa 1 hari", "Puasa 3 hari", "Puasa 3 hari dan memberi makan fakir miskin", "Tidak ada output", "Puasa 1 hari dan 3 hari"], "ans": 0, "why": "2.7 tidak > 3, tetapi >= 2.5, sehingga cabang else if yang dijalankan.", "lvl": 2, "code": "if (ipk > 3)\n    cout << \"Puasa 3 hari\";\nelse if (ipk >= 2.5)\n    cout << \"Puasa 1 hari\";\nelse\n    cout << \"Puasa 3 hari dan memberi makan fakir miskin\";", "src": "modul", "id": "P04-011"}, {"p": "P04", "tag": "elseif", "type": "mcq", "q": "Pada rantai if - else if, jika dua kondisi sama-sama benar, yang dijalankan adalah…", "opts": ["Hanya cabang pertama yang benar", "Keduanya", "Cabang terakhir", "Tidak ada", "Cabang else"], "ans": 0, "why": "Kondisi diperiksa dari atas; begitu satu bernilai true, cabang lain dilewati.", "lvl": 2, "code": null, "src": "modul", "id": "P04-012"}, {"p": "P04", "tag": "elseif", "type": "mcq", "q": "Output kode berikut untuk nilai = 85 adalah…", "opts": ["A", "B", "C", "AB", "Error"], "ans": 0, "why": "85 >= 80 true sehingga mencetak A dan sisa cabang dilewati.", "lvl": 2, "code": "if (nilai >= 80) cout << \"A\";\nelse if (nilai >= 70) cout << \"B\";\nelse cout << \"C\";", "src": "modul", "id": "P04-013"}, {"p": "P05", "tag": "nested", "type": "mcq", "q": "If bersarang (nested if) adalah…", "opts": ["Pernyataan if yang berada di dalam if lain", "if tanpa kondisi", "if yang diulang dengan for", "switch di dalam fungsi", "if yang hanya punya else"], "ans": 0, "why": "Nested if menaruh if di dalam blok if/else lain untuk kondisi bertingkat.", "lvl": 1, "code": null, "src": "modul", "id": "P05-001"}, {"p": "P05", "tag": "nested", "type": "mcq", "q": "Output kode berikut untuk umur = 20 dan punyaSIM = false adalah…", "opts": ["Buat SIM dulu", "Boleh mengemudi", "Belum cukup umur", "Tidak ada output", "Error"], "ans": 0, "why": "umur >= 17 true sehingga masuk if luar; punyaSIM false sehingga cabang else dalam dijalankan.", "lvl": 2, "code": "if (umur >= 17) {\n    if (punyaSIM) cout << \"Boleh mengemudi\";\n    else cout << \"Buat SIM dulu\";\n} else {\n    cout << \"Belum cukup umur\";\n}", "src": "modul", "id": "P05-002"}, {"p": "P05", "tag": "nested", "type": "mcq", "q": "Output kode nested if yang sama untuk umur = 15 adalah…", "opts": ["Belum cukup umur", "Buat SIM dulu", "Boleh mengemudi", "Tidak ada output", "Buat SIM dulu Belum cukup umur"], "ans": 0, "why": "Kondisi luar umur >= 17 false, jadi if dalam tidak pernah diperiksa dan else luar dijalankan.", "lvl": 2, "code": "if (umur >= 17) {\n    if (punyaSIM) cout << \"Boleh mengemudi\";\n    else cout << \"Buat SIM dulu\";\n} else {\n    cout << \"Belum cukup umur\";\n}", "src": "modul", "id": "P05-003"}, {"p": "P05", "tag": "switch", "type": "mcq", "q": "switch-case paling cocok dipakai untuk…", "opts": ["Pilihan dengan nilai pasti, misalnya menu 1, 2, 3", "Menguji rentang nilai seperti nilai > 80", "Mengulang perintah", "Menyimpan banyak data", "Membuat fungsi"], "ans": 0, "why": "Kisi-kisi: switch-case untuk kasus pilihan bernilai pasti; rentang tetap memakai if-else.", "lvl": 1, "code": null, "src": "modul", "id": "P05-004"}, {"p": "P05", "tag": "switch", "type": "mcq", "q": "Mengapa kondisi 'nilai > 80' tidak bisa langsung ditulis sebagai case?", "opts": ["case hanya mencocokkan nilai konstan tertentu, bukan rentang", "Karena switch hanya untuk string", "Karena > tidak ada di C++", "Karena harus memakai default", "Karena case harus berupa float"], "ans": 0, "why": "case membandingkan kesamaan dengan nilai konstan; untuk rentang gunakan if - else if.", "lvl": 2, "code": null, "src": "modul", "id": "P05-005"}, {"p": "P05", "tag": "switch", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["Selasa", "Senin", "Rabu", "Hari tidak valid", "SelasaRabu"], "ans": 0, "why": "hari bernilai 2 sehingga case 2 dijalankan, lalu break menghentikan switch.", "lvl": 1, "code": "int hari = 2;\nswitch (hari) {\n    case 1: cout << \"Senin\"; break;\n    case 2: cout << \"Selasa\"; break;\n    case 3: cout << \"Rabu\"; break;\n    default: cout << \"Hari tidak valid\";\n}", "src": "modul", "id": "P05-006"}, {"p": "P05", "tag": "break", "type": "mcq", "q": "Fungsi break di dalam switch adalah…", "opts": ["Menghentikan eksekusi switch agar tidak lanjut ke case berikutnya", "Mengulang switch", "Menjalankan default", "Melompati satu case", "Menghentikan program"], "ans": 0, "why": "Tanpa break, eksekusi terus 'jatuh' (fall-through) ke case di bawahnya.", "lvl": 1, "code": null, "src": "modul", "id": "P05-007"}, {"p": "P05", "tag": "break", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["BC", "B", "ABC", "C", "BCD"], "ans": 0, "why": "pilih = 2 masuk case 2 mencetak B, lalu tanpa break jatuh ke case 3 mencetak C, kemudian break.", "lvl": 3, "code": "int pilih = 2;\nswitch (pilih) {\n    case 1: cout << \"A\";\n    case 2: cout << \"B\";\n    case 3: cout << \"C\"; break;\n    default: cout << \"D\";\n}", "src": "modul", "id": "P05-008"}, {"p": "P05", "tag": "break", "type": "mcq", "q": "Bagian default pada switch dijalankan ketika…", "opts": ["Tidak ada case yang cocok", "Semua case cocok", "Selalu dijalankan pertama", "Hanya jika ada break", "Program error"], "ans": 0, "why": "default berperan seperti else: dijalankan bila tidak ada nilai case yang cocok.", "lvl": 1, "code": null, "src": "modul", "id": "P05-009"}, {"p": "P05", "tag": "break", "type": "mcq", "q": "Output kode berikut untuk kode = 9 adalah…", "opts": ["Tidak dikenal", "Satu", "Dua", "Tidak ada output", "SatuDua"], "ans": 0, "why": "Tidak ada case 9, jadi default dijalankan.", "lvl": 1, "code": "switch (kode) {\n    case 1: cout << \"Satu\"; break;\n    case 2: cout << \"Dua\"; break;\n    default: cout << \"Tidak dikenal\";\n}", "src": "modul", "id": "P05-010"}, {"p": "P06", "tag": "konsep", "type": "mcq", "q": "Tiga karakteristik perulangan menurut materi adalah…", "opts": ["Kondisi awal, syarat pengulangan, dan step pengulangan", "Input, proses, output", "Deklarasi, inisialisasi, assignment", "Header, body, footer", "case, break, default"], "ans": 0, "why": "Pengulangan punya titik awal, syarat yang membuatnya terus berjalan, dan step yang mengubah nilai.", "lvl": 1, "code": null, "src": "modul", "id": "P06-001"}, {"p": "P06", "tag": "konsep", "type": "mcq", "q": "Tiga bentuk perulangan di C++ adalah…", "opts": ["for, while, do-while", "if, else, switch", "for, if, switch", "while, case, break", "loop, repeat, until"], "ans": 0, "why": "C++ menyediakan while(), do...while(), dan for().", "lvl": 1, "code": null, "src": "modul", "id": "P06-002"}, {"p": "P06", "tag": "konsep", "type": "mcq", "q": "Perulangan for paling cocok ketika…", "opts": ["Jumlah pengulangan sudah diketahui", "Jumlah pengulangan tidak diketahui sama sekali", "Minimal harus jalan sekali tanpa cek", "Memilih satu dari banyak nilai", "Mengelompokkan data berbeda tipe"], "ans": 0, "why": "Kisi-kisi: for untuk pengulangan yang jumlahnya diketahui.", "lvl": 1, "code": null, "src": "modul", "id": "P06-003"}, {"p": "P06", "tag": "for", "type": "mcq", "q": "Urutan kerja for(inisialisasi; kondisi; step) yang benar adalah…", "opts": ["Inisialisasi sekali → cek kondisi → jalankan blok → step → cek kondisi lagi", "Step → inisialisasi → kondisi → blok", "Blok → kondisi → inisialisasi → step", "Kondisi → step → blok → inisialisasi", "Inisialisasi setiap putaran → blok → kondisi"], "ans": 0, "why": "Inisialisasi hanya sekali; lalu kondisi dicek, blok dijalankan, step dieksekusi, dan kembali ke cek kondisi.", "lvl": 1, "code": null, "src": "modul", "id": "P06-004"}, {"p": "P06", "tag": "for", "type": "mcq", "q": "Pada for (;n<10;), pernyataan yang benar adalah…", "opts": ["Inisialisasi dan step dikosongkan, tetapi titik koma tetap wajib", "Kode salah karena tidak ada inisialisasi", "Loop pasti berjalan 10 kali", "Kondisi diabaikan", "Tanda ; boleh dihapus"], "ans": 0, "why": "Ekspresi inisialisasi dan step bersifat opsional, tetapi pemisah ; harus tetap ada.", "lvl": 2, "code": null, "src": "modul", "id": "P06-005"}, {"p": "P06", "tag": "for", "type": "mcq", "q": "Berapa kali pernyataan di dalam for (int i = 0; i < 5; i++) dijalankan?", "opts": ["5", "4", "6", "0", "Tak terbatas"], "ans": 0, "why": "i bernilai 0,1,2,3,4 — lima kali; saat i = 5 kondisi i < 5 false.", "lvl": 1, "code": null, "src": "modul", "id": "P06-006"}, {"p": "P06", "tag": "for", "type": "mcq", "q": "Berapa kali for (int i = 1; i <= 5; i++) berulang?", "opts": ["5", "4", "6", "1", "0"], "ans": 0, "why": "i bernilai 1 sampai 5, jadi 5 kali.", "lvl": 1, "code": null, "src": "modul", "id": "P06-007"}, {"p": "P06", "tag": "trace", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["54321", "12345", "5432", "543210", "Tidak ada output"], "ans": 0, "why": "n dimulai 5, dicetak, lalu dikurangi; berhenti saat n = 0.", "lvl": 1, "code": "for (int n = 5; n > 0; n--) {\n    cout << n;\n}", "src": "modul", "id": "P06-008"}, {"p": "P06", "tag": "trace", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["0 2 4 6 8 ", "0 1 2 3 4 ", "2 4 6 8 10 ", "0 2 4 6 8 10 ", "1 3 5 7 9 "], "ans": 0, "why": "i mulai 0 dan bertambah 2 selama i < 10: 0,2,4,6,8.", "lvl": 2, "code": "for (int i = 0; i < 10; i += 2) {\n    cout << i << \" \";\n}", "src": "modul", "id": "P06-009"}, {"p": "P06", "tag": "trace", "type": "mcq", "q": "Nilai total setelah kode berikut adalah…", "opts": ["15", "10", "5", "6", "21"], "ans": 0, "why": "total = 1+2+3+4+5 = 15.", "lvl": 2, "code": "int total = 0;\nfor (int i = 1; i <= 5; i++) {\n    total += i;\n}", "src": "modul", "id": "P06-010"}, {"p": "P06", "tag": "trace", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["***", "****", "**", "*", "Tidak ada output"], "ans": 0, "why": "i bernilai 1,2,3 sehingga bintang dicetak 3 kali.", "lvl": 1, "code": "for (int i = 1; i <= 3; i++) cout << \"*\";", "src": "modul", "id": "P06-011"}, {"p": "P07", "tag": "while", "type": "mcq", "q": "Karakteristik while adalah…", "opts": ["Kondisi dicek terlebih dahulu sebelum blok dijalankan", "Blok selalu jalan minimal sekali", "Tidak memerlukan kondisi", "Hanya untuk jumlah ulangan tetap", "Selalu infinite loop"], "ans": 0, "why": "while memeriksa kondisi dulu; jika false sejak awal, blok tidak dijalankan sama sekali.", "lvl": 1, "code": null, "src": "modul", "id": "P07-001"}, {"p": "P07", "tag": "while", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["5,4,3,2,1,FIRE!", "5,4,3,2,1,0,FIRE!", "4,3,2,1,FIRE!", "FIRE!", "1,2,3,4,5,FIRE!"], "ans": 0, "why": "Selama n > 0, cetak n lalu kurangi; setelah n = 0 keluar loop dan mencetak FIRE!", "lvl": 2, "code": "int n = 5;\nwhile (n > 0) {\n    cout << n << \",\";\n    n--;\n}\ncout << \"FIRE!\";", "src": "modul", "id": "P07-002"}, {"p": "P07", "tag": "while", "type": "mcq", "q": "Berapa kali blok while berikut dijalankan?", "opts": ["0 kali", "1 kali", "10 kali", "Tak terbatas", "9 kali"], "ans": 0, "why": "Kondisi x < 5 sudah false sejak awal (x = 10), jadi while tidak menjalankan bloknya.", "lvl": 2, "code": "int x = 10;\nwhile (x < 5) {\n    x++;\n}", "src": "modul", "id": "P07-003"}, {"p": "P07", "tag": "dowhile", "type": "mcq", "q": "Perbedaan utama while dan do-while adalah…", "opts": ["do-while menjalankan blok minimal satu kali karena kondisi dicek di akhir", "while selalu lebih cepat", "do-while tidak memakai kondisi", "while minimal sekali, do-while bisa 0 kali", "Tidak ada perbedaan"], "ans": 0, "why": "do-while mengeksekusi blok dulu baru mengecek kondisi; while mengecek dulu.", "lvl": 1, "code": null, "src": "modul", "id": "P07-004"}, {"p": "P07", "tag": "dowhile", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["10", "Tidak ada output", "11", "0", "Error"], "ans": 0, "why": "do-while menjalankan blok sekali (mencetak 10) sebelum kondisi x < 5 diperiksa dan bernilai false.", "lvl": 2, "code": "int x = 10;\ndo {\n    cout << x;\n    x++;\n} while (x < 5);", "src": "modul", "id": "P07-005"}, {"p": "P07", "tag": "dowhile", "type": "mcq", "q": "Penulisan do-while yang benar adalah…", "opts": ["do { ... } while (kondisi);", "do (kondisi) { ... }", "while { ... } do (kondisi);", "do { ... } while kondisi", "do while (kondisi) { ... }"], "ans": 0, "why": "Bentuknya do { pernyataan } while (kondisi); — diakhiri titik koma.", "lvl": 1, "code": null, "src": "modul", "id": "P07-006"}, {"p": "P07", "tag": "dowhile", "type": "mcq", "q": "Situasi yang paling cocok memakai do-while adalah…", "opts": ["Menampilkan menu minimal sekali lalu mengulang selama pengguna belum memilih keluar", "Mencetak angka 1 sampai 10", "Menjumlahkan elemen array", "Memilih hari dari angka", "Membandingkan dua nilai"], "ans": 0, "why": "Menu harus tampil sedikitnya sekali sebelum pilihan dicek — sifat do-while.", "lvl": 2, "code": null, "src": "modul", "id": "P07-007"}, {"p": "P07", "tag": "nested", "type": "mcq", "q": "Infinite loop (perulangan tanpa akhir) terjadi ketika…", "opts": ["Step tidak pernah membuat kondisi menjadi false", "Kondisi bernilai false sejak awal", "Ada break di dalam loop", "Loop memakai for", "Variabel dideklarasikan di luar loop"], "ans": 0, "why": "Agar berhenti, step (mis. n--) harus suatu saat membuat kondisi false.", "lvl": 1, "code": null, "src": "modul", "id": "P07-008"}, {"p": "P07", "tag": "nested", "type": "mcq", "q": "Berapa kali tanda * dicetak?", "opts": ["12", "7", "3", "4", "16"], "ans": 0, "why": "Loop dalam (4 kali) berjalan penuh untuk setiap putaran loop luar (3 kali): 3 × 4 = 12.", "lvl": 2, "code": "for (int i = 0; i < 3; i++)\n    for (int j = 0; j < 4; j++)\n        cout << \"*\";", "src": "modul", "id": "P07-009"}, {"p": "P07", "tag": "nested", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["*\n**\n***", "***\n**\n*", "***\n***\n***", "*\n*\n*", "**\n**\n**"], "ans": 0, "why": "Pada baris ke-i, loop dalam mencetak i bintang, membentuk segitiga 1, 2, 3.", "lvl": 3, "code": "for (int i = 1; i <= 3; i++) {\n    for (int j = 1; j <= i; j++) cout << \"*\";\n    cout << endl;\n}", "src": "modul", "id": "P07-010"}, {"p": "P07", "tag": "nested", "type": "mcq", "q": "Kode while berikut akan…", "opts": ["Berulang terus tanpa henti (infinite loop)", "Berjalan 5 kali", "Tidak berjalan", "Berjalan sekali", "Error kompilasi"], "ans": 0, "why": "Tidak ada step yang mengubah i, sehingga i < 5 selalu true.", "lvl": 2, "code": "int i = 0;\nwhile (i < 5) {\n    cout << i;\n}", "src": "modul", "id": "P07-011"}, {"p": "P09", "tag": "konsep", "type": "mcq", "q": "Array (larik) adalah…", "opts": ["Kumpulan elemen bertipe sama yang dipanggil dengan nama yang sama", "Kumpulan variabel berbeda tipe", "Fungsi yang mengembalikan nilai", "Perulangan dengan indeks", "Tipe data boolean"], "ans": 0, "why": "Array menyimpan beberapa elemen dengan tipe sama dalam satu nama; berbeda tipe adalah struct.", "lvl": 1, "code": null, "src": "modul", "id": "P09-001"}, {"p": "P09", "tag": "konsep", "type": "mcq", "q": "Deklarasi int nilai[5]; berarti…", "opts": ["Array nilai memiliki 5 elemen bertipe int dengan indeks 0–4", "Array berisi angka 5", "Array memiliki 6 elemen", "Indeks dimulai dari 1 sampai 5", "Variabel int bernilai 5"], "ans": 0, "why": "Angka dalam kurung siku adalah jumlah elemen; indeks dimulai dari 0.", "lvl": 1, "code": null, "src": "modul", "id": "P09-002"}, {"p": "P09", "tag": "konsep", "type": "mcq", "q": "Ukuran memori unsigned short int arrayku[5] (short = 2 byte) adalah…", "opts": ["10 byte", "5 byte", "2 byte", "7 byte", "20 byte"], "ans": 0, "why": "Total byte = ukuran tipe × jumlah elemen = 2 × 5 = 10 byte.", "lvl": 2, "code": null, "src": "modul", "id": "P09-003"}, {"p": "P09", "tag": "konsep", "type": "mcq", "q": "Jika int = 4 byte, ukuran int data[8] adalah…", "opts": ["32 byte", "12 byte", "8 byte", "4 byte", "64 byte"], "ans": 0, "why": "4 byte × 8 elemen = 32 byte.", "lvl": 2, "code": null, "src": "modul", "id": "P09-004"}, {"p": "P09", "tag": "indeks", "type": "mcq", "q": "Indeks elemen pertama sebuah array di C++ adalah…", "opts": ["0", "1", "-1", "Tergantung ukuran", "n"], "ans": 0, "why": "Indeks array C++ selalu dimulai dari 0.", "lvl": 1, "code": null, "src": "modul", "id": "P09-005"}, {"p": "P09", "tag": "indeks", "type": "mcq", "q": "Pada int myarray[4] = {2,4,6,8}; nilai myarray[2] adalah…", "opts": ["6", "4", "8", "2", "Error"], "ans": 0, "why": "Indeks 0→2, 1→4, 2→6, 3→8.", "lvl": 1, "code": null, "src": "modul", "id": "P09-006"}, {"p": "P09", "tag": "indeks", "type": "mcq", "q": "Pada int larik[10]; pengaksesan yang SALAH adalah…", "opts": ["larik[10] = 2;", "larik[9] = larik[2];", "larik[8] = 1;", "larik[0] = 5;", "larik[5] = larik[4];"], "ans": 0, "why": "Array 10 elemen punya indeks 0–9; larik[10] melewati batas.", "lvl": 1, "code": null, "src": "modul", "id": "P09-007"}, {"p": "P09", "tag": "indeks", "type": "mcq", "q": "Indeks elemen terakhir pada array berukuran n adalah…", "opts": ["n - 1", "n", "n + 1", "1", "0"], "ans": 0, "why": "Karena indeks mulai dari 0, elemen terakhir ada di n - 1.", "lvl": 1, "code": null, "src": "modul", "id": "P09-008"}, {"p": "P09", "tag": "indeks", "type": "mcq", "q": "Jika arrayku = {10, 20, 30, 40, 50} dan X = arrayku[1] / 10, maka arrayku[X+1] bernilai…", "opts": ["40", "30", "20", "50", "Error"], "ans": 0, "why": "arrayku[1] = 20 sehingga X = 2; arrayku[X+1] = arrayku[3] = 40.", "lvl": 3, "code": null, "src": "modul", "id": "P09-009"}, {"p": "P09", "tag": "olah", "type": "mcq", "q": "Pernyataan a = b; untuk dua array int a[5], b[5] adalah…", "opts": ["Salah; array harus disalin per elemen, misalnya dengan for", "Benar dan menyalin semua elemen", "Benar tetapi hanya elemen pertama", "Menggabungkan a dan b", "Membandingkan a dan b"], "ans": 0, "why": "Elemen array tidak bisa diakses bersamaan; salin satu per satu: for(i=0;i<5;i++) a[i]=b[i];", "lvl": 1, "code": null, "src": "modul", "id": "P09-010"}, {"p": "P09", "tag": "olah", "type": "mcq", "q": "Kode untuk menyalin seluruh elemen b ke a (5 elemen) yang benar adalah…", "opts": ["for (i = 0; i < 5; i++) a[i] = b[i];", "a = b;", "a[5] = b[5];", "for (i = 1; i <= 5; i++) a = b;", "copy a, b;"], "ans": 0, "why": "Setiap elemen disalin individual memakai indeks 0 sampai 4.", "lvl": 1, "code": null, "src": "modul", "id": "P09-011"}, {"p": "P09", "tag": "olah", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["15", "5", "6", "14", "0"], "ans": 0, "why": "Loop menjumlahkan 1+2+3+4+5 = 15.", "lvl": 2, "code": "int a[5] = {1, 2, 3, 4, 5};\nint s = 0;\nfor (int i = 0; i < 5; i++) s += a[i];\ncout << s;", "src": "modul", "id": "P09-012"}, {"p": "P09", "tag": "olah", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["9", "3", "7", "5", "1"], "ans": 0, "why": "Loop mencari nilai terbesar; elemen terbesar adalah 9.", "lvl": 2, "code": "int a[5] = {3, 7, 1, 9, 5};\nint mx = a[0];\nfor (int i = 1; i < 5; i++)\n    if (a[i] > mx) mx = a[i];\ncout << mx;", "src": "modul", "id": "P09-013"}, {"p": "P10", "tag": "konsep", "type": "mcq", "q": "struct digunakan untuk…", "opts": ["Mengelompokkan beberapa variabel dengan tipe data berbeda menjadi satu tipe baru", "Mengulang perintah", "Menyimpan data bertipe sama saja", "Memilih satu dari banyak nilai", "Menerjemahkan kode"], "ans": 0, "why": "struct membuat tipe data baru berisi field-field yang boleh berbeda tipe (sebuah record).", "lvl": 1, "code": null, "src": "modul", "id": "P10-001"}, {"p": "P10", "tag": "konsep", "type": "mcq", "q": "Perbedaan utama array dan struct adalah…", "opts": ["Array berisi elemen bertipe sama, struct dapat berisi field berbeda tipe", "Array untuk teks, struct untuk angka", "Struct tidak bisa menyimpan string", "Array tidak memakai indeks", "Tidak ada bedanya"], "ans": 0, "why": "Materi: struct adalah pengembangan dari array yang dapat menampung tipe data berbeda.", "lvl": 1, "code": null, "src": "modul", "id": "P10-002"}, {"p": "P10", "tag": "konsep", "type": "mcq", "q": "Deklarasi struct yang benar adalah…", "opts": ["struct Produk { string nama; float harga; };", "struct Produk ( string nama; float harga; )", "Produk struct { nama; harga; }", "struct { Produk: nama, harga }", "struct Produk = { string nama, float harga }"], "ans": 0, "why": "Bentuknya struct Nama { tipe field; ... }; — diakhiri titik koma.", "lvl": 1, "code": null, "src": "modul", "id": "P10-003"}, {"p": "P10", "tag": "konsep", "type": "mcq", "q": "Variabel yang dideklarasikan di dalam struct disebut…", "opts": ["Member (field)", "Parameter", "Indeks", "Keyword", "Prototype"], "ans": 0, "why": "Member adalah variabel di dalam struct yang menjadi bagian dari struct itu.", "lvl": 1, "code": null, "src": "modul", "id": "P10-004"}, {"p": "P10", "tag": "akses", "type": "mcq", "q": "Operator untuk mengakses member struct dari sebuah object adalah…", "opts": ["Titik (.)", "Panah ganda (>>)", "Titik dua (:)", "Kurung siku []", "Tanda pagar (#)"], "ans": 0, "why": "Member access operator berupa titik di antara nama object dan nama member, misalnya p.harga.", "lvl": 1, "code": null, "src": "modul", "id": "P10-005"}, {"p": "P10", "tag": "akses", "type": "mcq", "q": "Mengapa member struct belum bisa dipakai sebelum object dibuat?", "opts": ["Struct hanya rancangan tipe data; data baru ada setelah object dideklarasikan", "Karena member bersifat private", "Karena struct harus di dalam main", "Karena compiler belum membaca iostream", "Karena struct hanya untuk array"], "ans": 0, "why": "Materi: struct hanyalah rancangan tipe; harus didirikan object (mis. Produk p;) dulu.", "lvl": 2, "code": null, "src": "modul", "id": "P10-006"}, {"p": "P10", "tag": "akses", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["Buku 25000", "nama harga", "Buku", "25000", "Error"], "ans": 0, "why": "Member nama dan harga diakses dengan titik, lalu dicetak.", "lvl": 2, "code": "struct Produk { string nama; int harga; };\nProduk p;\np.nama = \"Buku\";\np.harga = 25000;\ncout << p.nama << \" \" << p.harga;", "src": "modul", "id": "P10-007"}, {"p": "P10", "tag": "akses", "type": "mcq", "q": "Untuk record produk (kode, nama, harga), tipe field harga yang paling tepat adalah…", "opts": ["float", "bool", "char", "string", "void"], "ans": 0, "why": "Contoh materi: struct ProductRec { string name; string idNum; float price; };", "lvl": 1, "code": null, "src": "modul", "id": "P10-008"}, {"p": "P10", "tag": "array", "type": "mcq", "q": "Cara mengakses NIM mahasiswa ketiga pada Mahasiswa mhs[30]; adalah…", "opts": ["mhs[2].nim", "mhs.nim[2]", "mhs[3].nim", "nim.mhs[2]", "mhs(2).nim"], "ans": 0, "why": "Indeks array dimulai dari 0, jadi mahasiswa ketiga di indeks 2; lalu akses field dengan titik.", "lvl": 2, "code": null, "src": "modul", "id": "P10-009"}, {"p": "P10", "tag": "array", "type": "mcq", "q": "Kegunaan array of struct adalah…", "opts": ["Menyimpan banyak record dengan struktur yang sama, misalnya data 30 mahasiswa", "Menyimpan satu nilai boolean", "Mengganti fungsi", "Menghapus field struct", "Mempercepat compiler"], "ans": 0, "why": "Array of struct menampung banyak record sekaligus; tiap elemen memiliki semua field.", "lvl": 1, "code": null, "src": "modul", "id": "P10-010"}, {"p": "P11", "tag": "konsep", "type": "mcq", "q": "Fungsi adalah…", "opts": ["Bagian program terpisah yang dibuat untuk mengerjakan tugas tertentu", "Tipe data untuk teks", "Simbol flowchart", "Variabel global", "Jenis perulangan"], "ans": 0, "why": "Fungsi adalah subprogram untuk tugas tertentu yang letaknya terpisah dari program pemanggilnya.", "lvl": 1, "code": null, "src": "modul", "id": "P11-001"}, {"p": "P11", "tag": "konsep", "type": "mcq", "q": "Dua keuntungan fungsi menurut materi adalah…", "opts": ["Struktur program jelas (readability) dan dapat dipakai ulang (reusability)", "Program lebih panjang dan lambat", "Tidak perlu variabel dan tipe data", "Tidak perlu main()", "Menghindari penggunaan loop"], "ans": 0, "why": "Fungsi membuat struktur jelas dan bisa digunakan kembali sehingga tidak menulis bagian yang sama berulang.", "lvl": 1, "code": null, "src": "modul", "id": "P11-002"}, {"p": "P11", "tag": "konsep", "type": "mcq", "q": "Setiap program C/C++ minimal memiliki satu fungsi, yaitu…", "opts": ["main()", "cout()", "printf()", "fungsi()", "start()"], "ans": 0, "why": "Program selalu punya main() sebagai titik awal eksekusi.", "lvl": 1, "code": null, "src": "modul", "id": "P11-003"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Fungsi pustaka untuk menghitung akar kuadrat adalah…", "opts": ["sqrt()", "pow()", "strlen()", "abs()", "toupper()"], "ans": 0, "why": "sqrt() (math.h/cmath) menghitung akar sebuah bilangan.", "lvl": 1, "code": null, "src": "modul", "id": "P11-004"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Nilai pow(2, 3) adalah…", "opts": ["8", "6", "9", "5", "23"], "ans": 0, "why": "pow(bilangan, pangkat) = 2³ = 8.", "lvl": 1, "code": null, "src": "modul", "id": "P11-005"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Fungsi untuk mengetahui jumlah karakter sebuah string (string.h) adalah…", "opts": ["strlen()", "strcpy()", "strcat()", "strupr()", "sizeof()"], "ans": 0, "why": "strlen() menghasilkan jumlah karakter; strcpy menyalin, strcat menyambung.", "lvl": 1, "code": null, "src": "modul", "id": "P11-006"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "toupper('a') menghasilkan…", "opts": ["'A'", "'a'", "1", "0", "\"A\" dalam bentuk string"], "ans": 0, "why": "toupper mengubah huruf kecil menjadi huruf kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P11-007"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Fungsi strcat(tujuan, sumber) berfungsi untuk…", "opts": ["Menambahkan string sumber ke akhir string tujuan", "Menyalin string", "Menghitung panjang string", "Mengubah ke huruf kapital", "Membandingkan dua string"], "ans": 0, "why": "strcat menyambung (concatenate) string sumber di belakang string tujuan.", "lvl": 1, "code": null, "src": "modul", "id": "P11-008"}, {"p": "P11", "tag": "deklarasi", "type": "mcq", "q": "Bentuk umum pendefinisian fungsi adalah…", "opts": ["tipe_fungsi nama_fungsi(parameter) { pernyataan }", "nama_fungsi tipe(parameter);", "function nama() {}", "def nama(parameter):", "nama_fungsi = (parameter) => {}"], "ans": 0, "why": "C++: tipe kembalian, nama, daftar parameter dalam kurung, lalu blok isi fungsi.", "lvl": 1, "code": null, "src": "modul", "id": "P11-009"}, {"p": "P11", "tag": "deklarasi", "type": "mcq", "q": "Prototype fungsi adalah…", "opts": ["Deklarasi fungsi (tipe, nama, parameter) yang ditulis sebelum fungsi dipakai", "Isi lengkap fungsi", "Pemanggilan fungsi", "Komentar di atas fungsi", "Fungsi pustaka"], "ans": 0, "why": "Prototype = pendeklarasian fungsi, mis. int jumlah(int a, int b); — diperlukan jika definisi ada setelah main.", "lvl": 1, "code": null, "src": "modul", "id": "P11-010"}, {"p": "P11", "tag": "deklarasi", "type": "mcq", "q": "Fungsi bertipe void artinya…", "opts": ["Tidak mengembalikan nilai", "Mengembalikan bilangan bulat", "Tidak boleh punya parameter", "Tidak bisa dipanggil", "Selalu mengembalikan 0"], "ans": 0, "why": "void menandakan fungsi tidak mengembalikan nilai; biasanya untuk mencetak atau prosedur.", "lvl": 1, "code": null, "src": "modul", "id": "P11-011"}, {"p": "P11", "tag": "deklarasi", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["Halo Halo ", "Halo ", "Tidak ada output", "sapa sapa", "Error"], "ans": 0, "why": "Fungsi void sapa() dipanggil dua kali sehingga mencetak dua kali.", "lvl": 2, "code": "void sapa() { cout << \"Halo \"; }\nint main() {\n    sapa();\n    sapa();\n}", "src": "modul", "id": "P11-012"}, {"p": "P12", "tag": "parameter", "type": "mcq", "q": "Pada int tambah(int x, int y), x dan y disebut…", "opts": ["Parameter formal", "Argumen aktual", "Nilai balik", "Variabel global", "Keyword"], "ans": 0, "why": "Parameter yang tertulis pada definisi fungsi disebut parameter formal; nilai saat pemanggilan adalah argumen/aktual.", "lvl": 1, "code": null, "src": "modul", "id": "P12-001"}, {"p": "P12", "tag": "parameter", "type": "mcq", "q": "Pada pemanggilan tambah(3, 4), angka 3 dan 4 disebut…", "opts": ["Argumen (parameter aktual)", "Parameter formal", "Tipe fungsi", "Prototype", "Return"], "ans": 0, "why": "Nilai yang dikirim ketika memanggil fungsi disebut argumen atau parameter aktual.", "lvl": 1, "code": null, "src": "modul", "id": "P12-002"}, {"p": "P12", "tag": "return", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["7", "34", "x+y", "0", "Error"], "ans": 0, "why": "tambah(3,4) mengembalikan 3 + 4 = 7.", "lvl": 1, "code": "int tambah(int x, int y) {\n    return x + y;\n}\nint main() {\n    cout << tambah(3, 4);\n}", "src": "modul", "id": "P12-003"}, {"p": "P12", "tag": "return", "type": "mcq", "q": "Fungsi pernyataan return adalah…", "opts": ["Mengirim nilai balik ke pemanggil dan menghentikan fungsi", "Mengulang fungsi", "Mencetak nilai ke layar", "Mendeklarasikan variabel", "Memanggil main"], "ans": 0, "why": "return mengembalikan nilai dan mengakhiri eksekusi fungsi.", "lvl": 1, "code": null, "src": "modul", "id": "P12-004"}, {"p": "P12", "tag": "return", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["25", "10", "5", "55", "Error"], "ans": 0, "why": "kuadrat(5) mengembalikan 5 × 5 = 25.", "lvl": 1, "code": "int kuadrat(int n) { return n * n; }\ncout << kuadrat(5);", "src": "modul", "id": "P12-005"}, {"p": "P12", "tag": "return", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["Genap", "Ganjil", "GenapGanjil", "4", "Tidak ada output"], "ans": 0, "why": "cekGenap(4) mengembalikan true (4 % 2 == 0), sehingga mencetak Genap.", "lvl": 2, "code": "bool cekGenap(int n) { return n % 2 == 0; }\nif (cekGenap(4)) cout << \"Genap\";\nelse cout << \"Ganjil\";", "src": "modul", "id": "P12-006"}, {"p": "P12", "tag": "referensi", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["5", "6", "0", "Error", "56"], "ans": 0, "why": "Pass by value: fungsi mengubah salinan, variabel a di main tetap 5.", "lvl": 2, "code": "void ubah(int x) { x = x + 1; }\nint main() {\n    int a = 5;\n    ubah(a);\n    cout << a;\n}", "src": "modul", "id": "P12-007"}, {"p": "P12", "tag": "referensi", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["6", "5", "0", "Error", "56"], "ans": 0, "why": "Parameter referensi (int &x) bekerja pada variabel asli, sehingga a menjadi 6.", "lvl": 2, "code": "void ubah(int &x) { x = x + 1; }\nint main() {\n    int a = 5;\n    ubah(a);\n    cout << a;\n}", "src": "modul", "id": "P12-008"}, {"p": "P12", "tag": "referensi", "type": "mcq", "q": "Kapan parameter referensi (&) dipakai?", "opts": ["Saat fungsi perlu mengubah nilai variabel asli pemanggil", "Saat fungsi tidak punya parameter", "Saat fungsi bertipe void saja", "Saat ingin menyalin nilai", "Saat memanggil fungsi pustaka"], "ans": 0, "why": "Dengan & fungsi menerima alias variabel asli, sehingga perubahannya terbawa keluar fungsi (mis. fungsi tukar).", "lvl": 1, "code": null, "src": "modul", "id": "P12-009"}, {"p": "P12", "tag": "rekursif", "type": "mcq", "q": "Fungsi rekursif adalah…", "opts": ["Fungsi yang memanggil dirinya sendiri", "Fungsi tanpa parameter", "Fungsi pustaka", "Fungsi yang dipanggil dari main", "Fungsi bertipe void"], "ans": 0, "why": "Rekursif = fungsi memanggil dirinya sendiri, dengan kondisi berhenti (base case).", "lvl": 1, "code": null, "src": "modul", "id": "P12-010"}, {"p": "P12", "tag": "rekursif", "type": "mcq", "q": "Bagian wajib pada fungsi rekursif agar tidak berjalan tanpa akhir adalah…", "opts": ["Base case (kondisi berhenti)", "Prototype", "Parameter referensi", "Tipe void", "Komentar"], "ans": 0, "why": "Tanpa base case, fungsi memanggil dirinya terus sampai memori habis (stack overflow).", "lvl": 1, "code": null, "src": "modul", "id": "P12-011"}, {"p": "P12", "tag": "rekursif", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["24", "4", "10", "12", "1"], "ans": 0, "why": "faktorial(4) = 4 × 3 × 2 × 1 = 24.", "lvl": 2, "code": "int faktorial(int n) {\n    if (n <= 1) return 1;\n    return n * faktorial(n - 1);\n}\ncout << faktorial(4);", "src": "modul", "id": "P12-012"}, {"p": "P13", "tag": "konsep", "type": "mcq", "q": "Menurut Levitin, algoritma adalah…", "opts": ["Urutan instruksi yang jelas untuk memperoleh output dari setiap input yang sah dalam waktu terbatas", "Program yang sudah dikompilasi", "Kumpulan data terurut", "Bahasa pemrograman", "Perangkat keras komputer"], "ans": 0, "why": "Definisi Levitin (2012) yang dipakai di materi sorting.", "lvl": 1, "code": null, "src": "modul", "id": "P13-001"}, {"p": "P13", "tag": "konsep", "type": "mcq", "q": "Pendekatan brute force dalam pengurutan berarti…", "opts": ["Pendekatan langsung yang paling mudah diimplementasikan", "Pendekatan dengan kecerdasan buatan", "Mengurutkan secara acak", "Pendekatan yang selalu tercepat", "Menggunakan perangkat keras khusus"], "ans": 0, "why": "Brute force adalah cara 'mudah' dan langsung; contohnya bubble sort dan selection sort.", "lvl": 1, "code": null, "src": "modul", "id": "P13-002"}, {"p": "P13", "tag": "konsep", "type": "mcq", "q": "Hasil FPB(12, 8) dengan algoritma Euclid adalah…", "opts": ["4", "2", "8", "12", "24"], "ans": 0, "why": "12 mod 8 = 4 → (8,4); 8 mod 4 = 0 → (4,0); n = 0 maka FPB = 4.", "lvl": 2, "code": null, "src": "modul", "id": "P13-003"}, {"p": "P13", "tag": "konsep", "type": "mcq", "q": "Pada algoritma Euclid, perulangan berhenti ketika…", "opts": ["n bernilai 0", "m bernilai 0", "m sama dengan n", "r bernilai 1", "m lebih kecil dari n"], "ans": 0, "why": "while n ≠ 0 do ...; saat n = 0, m adalah FPB.", "lvl": 2, "code": null, "src": "modul", "id": "P13-004"}, {"p": "P13", "tag": "selection", "type": "mcq", "q": "Cara kerja selection sort adalah…", "opts": ["Mencari elemen terkecil di bagian belum urut lalu menukarnya ke posisi paling depan bagian itu", "Membandingkan pasangan bersebelahan dan menukar jika salah urutan", "Membagi data menjadi dua lalu menggabungkan", "Mencari kunci satu per satu", "Menyisipkan elemen ke tempatnya"], "ans": 0, "why": "Selection sort memindai seluruh elemen, memilih minimum, dan menukarnya dengan elemen pertama bagian belum urut.", "lvl": 1, "code": null, "src": "modul", "id": "P13-005"}, {"p": "P13", "tag": "selection", "type": "mcq", "q": "Data 90 50 70 95 30 35 15 diurutkan naik dengan selection sort. Hasil setelah putaran pertama adalah…", "opts": ["15 50 70 95 30 35 90", "50 70 90 30 35 15 95", "15 30 70 95 50 35 90", "90 50 70 95 30 35 15", "15 30 35 50 70 90 95"], "ans": 0, "why": "Elemen terkecil (15) ditukar dengan elemen pertama (90).", "lvl": 2, "code": null, "src": "modul", "id": "P13-006"}, {"p": "P13", "tag": "selection", "type": "mcq", "q": "Melanjutkan contoh materi, hasil setelah putaran kedua adalah…", "opts": ["15 30 70 95 50 35 90", "15 50 70 95 30 35 90", "15 30 35 95 50 70 90", "15 30 70 50 95 35 90", "30 15 70 95 50 35 90"], "ans": 0, "why": "Dari bagian 50 70 95 30 35 90, minimum 30 ditukar dengan 50.", "lvl": 3, "code": null, "src": "modul", "id": "P13-007"}, {"p": "P13", "tag": "bubble", "type": "mcq", "q": "Cara kerja bubble sort adalah…", "opts": ["Membandingkan dua elemen bersebelahan dan menukarnya jika urutannya salah, diulang tiap putaran", "Mencari minimum lalu menukarnya ke depan", "Mencari kunci dari awal ke akhir", "Membagi data menjadi dua bagian", "Mengurutkan dengan menghapus elemen"], "ans": 0, "why": "Bubble sort menukar pasangan bersebelahan sehingga elemen terbesar 'menggelembung' ke akhir.", "lvl": 1, "code": null, "src": "modul", "id": "P13-008"}, {"p": "P13", "tag": "bubble", "type": "mcq", "q": "Data 5 1 4 2 diurutkan naik dengan bubble sort. Hasil setelah putaran pertama adalah…", "opts": ["1 4 2 5", "1 2 4 5", "1 5 4 2", "5 4 2 1", "4 1 2 5"], "ans": 0, "why": "(5,1) tukar → 1 5 4 2; (5,4) tukar → 1 4 5 2; (5,2) tukar → 1 4 2 5.", "lvl": 2, "code": null, "src": "modul", "id": "P13-009"}, {"p": "P13", "tag": "bubble", "type": "mcq", "q": "Untuk mengurutkan n elemen, bubble sort dan selection sort membutuhkan paling banyak…", "opts": ["n - 1 putaran luar", "n + 1 putaran", "1 putaran", "2n putaran", "n² putaran luar"], "ans": 0, "why": "Setelah n-1 putaran, n-1 elemen sudah di tempatnya sehingga elemen terakhir otomatis benar.", "lvl": 2, "code": null, "src": "modul", "id": "P13-010"}, {"p": "P13", "tag": "bubble", "type": "mcq", "q": "Setelah putaran pertama bubble sort (urut naik), elemen yang pasti sudah di posisi akhirnya adalah…", "opts": ["Elemen terbesar, di posisi paling belakang", "Elemen terkecil, di posisi paling depan", "Elemen tengah", "Tidak ada", "Elemen pertama"], "ans": 0, "why": "Pada tiap putaran, nilai terbesar dari bagian belum urut terdorong ke ujung kanan.", "lvl": 2, "code": null, "src": "modul", "id": "P13-011"}, {"p": "P14", "tag": "konsep", "type": "mcq", "q": "Sequential search bekerja dengan cara…", "opts": ["Membandingkan kunci dengan elemen satu per satu dari awal sampai ditemukan atau data habis", "Membagi data menjadi dua lalu memilih separuh", "Mengurutkan data dulu", "Menebak posisi secara acak", "Membandingkan elemen bersebelahan"], "ans": 0, "why": "Sequential search adalah pencarian brute force yang membandingkan kunci dengan setiap elemen secara berurutan.", "lvl": 1, "code": null, "src": "modul", "id": "P14-001"}, {"p": "P14", "tag": "konsep", "type": "mcq", "q": "Kapan proses sequential search berhenti?", "opts": ["Saat kunci cocok dengan elemen, atau semua elemen sudah diperiksa", "Selalu setelah memeriksa semua elemen", "Setelah setengah data", "Setelah elemen pertama", "Saat data terurut"], "ans": 0, "why": "Proses berhenti begitu kunci ditemukan, tanpa harus membandingkan semua elemen.", "lvl": 1, "code": null, "src": "modul", "id": "P14-002"}, {"p": "P14", "tag": "konsep", "type": "mcq", "q": "Nilai yang dikembalikan sequential search jika kunci tidak ditemukan adalah…", "opts": ["-1", "0", "n", "Kunci itu sendiri", "null"], "ans": 0, "why": "Pseudocode: if i < n return i else return -1.", "lvl": 1, "code": null, "src": "modul", "id": "P14-003"}, {"p": "P14", "tag": "konsep", "type": "mcq", "q": "Apakah sequential search memerlukan data terurut?", "opts": ["Tidak, bisa dipakai pada data tidak terurut", "Ya, wajib terurut naik", "Ya, wajib terurut turun", "Hanya untuk data string", "Hanya jika n genap"], "ans": 0, "why": "Karena memeriksa setiap elemen, urutan data tidak menjadi syarat.", "lvl": 1, "code": null, "src": "modul", "id": "P14-004"}, {"p": "P14", "tag": "trace", "type": "mcq", "q": "Tabel A = {3,1,2,4,6} dan kunci K = 5. Hasil sequential search adalah…", "opts": ["-1 (tidak ditemukan)", "3", "4", "0", "5"], "ans": 0, "why": "5 tidak ada di A sehingga semua elemen diperiksa dan fungsi mengembalikan -1.", "lvl": 1, "code": null, "src": "modul", "id": "P14-005"}, {"p": "P14", "tag": "trace", "type": "mcq", "q": "Tabel A = {10,12,9,7,20} dan kunci K = 9. Hasil sequential search adalah…", "opts": ["2", "3", "1", "9", "-1"], "ans": 0, "why": "Indeks 0 = 10, 1 = 12, 2 = 9 cocok → mengembalikan 2.", "lvl": 1, "code": null, "src": "modul", "id": "P14-006"}, {"p": "P14", "tag": "trace", "type": "mcq", "q": "Pada A = {10,12,9,7,20} dengan K = 9, berapa perbandingan yang dilakukan?", "opts": ["3", "5", "2", "1", "4"], "ans": 0, "why": "Dibandingkan dengan 10, 12, lalu 9 (cocok) — 3 perbandingan.", "lvl": 2, "code": null, "src": "modul", "id": "P14-007"}, {"p": "P14", "tag": "trace", "type": "mcq", "q": "Kondisi while pada pseudocode sequential search adalah…", "opts": ["i < n and A[i] ≠ K", "i < n or A[i] = K", "A[i] = K", "i > n", "i ≤ n and A[i] = K"], "ans": 0, "why": "Loop berlanjut selama masih dalam batas dan elemen belum cocok dengan kunci.", "lvl": 2, "code": null, "src": "modul", "id": "P14-008"}, {"p": "P15", "tag": "cpp", "type": "mcq", "q": "Implementasi sequential search di C++ yang benar adalah…", "opts": ["for (int i = 0; i < n; i++) if (A[i] == K) return i; return -1;", "for (int i = 0; i < n; i++) if (A[i] = K) return i;", "while (A[i] != K) i--; return i;", "for (int i = 1; i <= n; i++) return A[i];", "if (A == K) return 1;"], "ans": 0, "why": "Bandingkan dengan ==, kembalikan indeks saat cocok; jika loop selesai, kembalikan -1.", "lvl": 1, "code": null, "src": "modul", "id": "P15-001"}, {"p": "P15", "tag": "cpp", "type": "mcq", "q": "Pada data A = {4, 8, 8, 2}, sequential search dengan K = 8 mengembalikan…", "opts": ["1", "2", "1 dan 2", "0", "-1"], "ans": 0, "why": "Pencarian berhenti di kemunculan pertama, yaitu indeks 1.", "lvl": 2, "code": null, "src": "modul", "id": "P15-002"}, {"p": "P15", "tag": "cpp", "type": "mcq", "q": "Jumlah perbandingan terbanyak (kasus terburuk) sequential search pada n elemen adalah…", "opts": ["n", "1", "n/2", "2n", "log n"], "ans": 0, "why": "Kasus terburuk terjadi saat kunci di akhir atau tidak ada, sehingga semua n elemen diperiksa.", "lvl": 2, "code": null, "src": "modul", "id": "P15-003"}, {"p": "P15", "tag": "sentinel", "type": "mcq", "q": "Teknik sentinel pada sequential search adalah…", "opts": ["Menambahkan kunci K sebagai elemen fiktif setelah elemen terakhir", "Mengurutkan data dulu", "Mencari dari belakang", "Menghapus elemen yang tidak cocok", "Membagi data menjadi dua"], "ans": 0, "why": "Sentinel: A[n] ← K sehingga pencarian pasti menemukan kunci.", "lvl": 1, "code": null, "src": "modul", "id": "P15-004"}, {"p": "P15", "tag": "sentinel", "type": "mcq", "q": "Keuntungan teknik sentinel adalah…", "opts": ["Loop tidak perlu memeriksa batas i < n karena kunci pasti ditemukan", "Data menjadi terurut", "Bisa mencari dua kunci sekaligus", "Tidak memerlukan array", "Hasil selalu indeks 0"], "ans": 0, "why": "Karena kunci pasti ada (di A[n]), kondisi loop cukup A[i] ≠ K.", "lvl": 2, "code": null, "src": "modul", "id": "P15-005"}, {"p": "P15", "tag": "sentinel", "type": "mcq", "q": "Setelah loop sentinel berhenti di i = n, artinya…", "opts": ["Kunci tidak ada di data asli; yang ditemukan hanya sentinel, jadi kembalikan -1", "Kunci ada di indeks n", "Kunci ada di indeks 0", "Terjadi error", "Data harus diurutkan"], "ans": 0, "why": "Jika i < n kunci ditemukan di data asli; jika i = n berarti hanya cocok dengan sentinel.", "lvl": 2, "code": null, "src": "modul", "id": "P15-006"}, {"p": "P15", "tag": "sentinel", "type": "mcq", "q": "A = {3,1,2,4,6}, n = 5, K = 5 dengan sentinel. Isi A[5] dan hasil akhirnya adalah…", "opts": ["A[5] = 5, hasil -1", "A[5] = 6, hasil 4", "A[5] = 5, hasil 5", "A[5] = 0, hasil -1", "A[5] = 5, hasil 0"], "ans": 0, "why": "Sentinel menaruh K di A[5]; loop berhenti di i = 5 = n sehingga hasilnya -1.", "lvl": 3, "code": null, "src": "modul", "id": "P15-007"}, {"p": "P15", "tag": "semua", "type": "mcq", "q": "Untuk mencari SEMUA kemunculan kunci, modifikasi yang tepat adalah…", "opts": ["Jangan berhenti saat ketemu; lanjutkan loop dan catat/hitung setiap indeks yang cocok", "Berhenti di kemunculan pertama", "Mengurutkan data dulu", "Menggunakan sentinel", "Mencari dari indeks terakhir saja"], "ans": 0, "why": "Pencarian semua kemunculan terus memeriksa sampai akhir array dan mencatat setiap kecocokan.", "lvl": 1, "code": null, "src": "modul", "id": "P15-008"}, {"p": "P15", "tag": "semua", "type": "mcq", "q": "Output kode berikut adalah…", "opts": ["2", "1", "3", "0", "-1"], "ans": 0, "why": "Angka 8 muncul di indeks 1 dan 3 sehingga jumlah = 2.", "lvl": 2, "code": "int A[5] = {4, 8, 2, 8, 5};\nint jml = 0;\nfor (int i = 0; i < 5; i++)\n    if (A[i] == 8) jml++;\ncout << jml;", "src": "modul", "id": "P15-009"}], "cards": [{"id": "P01-C001", "p": "P01", "tag": "algoritma", "front": "Algoritma", "back": "Urutan langkah logis & terbatas untuk menyelesaikan masalah (asal kata: Al-Khwarizmi)."}, {"id": "P01-C002", "p": "P01", "tag": "notasi", "front": "Pseudocode vs Flowchart", "back": "Pseudocode: teks mirip kode untuk manusia. Flowchart: diagram simbol grafis."}, {"id": "P01-C003", "p": "P01", "tag": "notasi", "front": "Simbol flowchart", "back": "Oval = mulai/selesai · Persegi = proses · Jajar genjang = input/output · Belah ketupat = keputusan"}, {"id": "P01-C004", "p": "P01", "tag": "kompilasi", "front": "Compiler", "back": "Menerjemahkan kode sumber (bahasa tingkat tinggi) menjadi bahasa mesin."}, {"id": "P02-C001", "p": "P02", "tag": "struktur", "front": "Kerangka program C++", "back": "#include <iostream>\nusing namespace std;\nint main() {\n  cout << \"Halo\";\n  return 0;\n}"}, {"id": "P02-C002", "p": "P02", "tag": "variabel", "front": "Aturan nama variabel", "back": "Diawali huruf/_ · tanpa spasi · tanpa tanda minus · bukan keyword · case sensitive"}, {"id": "P02-C003", "p": "P02", "tag": "tipe", "front": "Tipe data dasar", "back": "int bulat · float/double pecahan · char 1 karakter · string teks · bool true/false"}, {"id": "P02-C004", "p": "P02", "tag": "io", "front": "cout vs cin", "back": "cout << (insertion) untuk output · cin >> (extraction) untuk input"}, {"id": "P03-C001", "p": "P03", "tag": "aritmetika", "front": "% (modulus)", "back": "Sisa bagi: 17 % 5 = 2. Genap jika x % 2 == 0."}, {"id": "P03-C002", "p": "P03", "tag": "aritmetika", "front": "int / int", "back": "Hasil dibulatkan ke bawah (dipotong): 7 / 2 = 3"}, {"id": "P03-C003", "p": "P03", "tag": "inc", "front": "x++ vs ++x", "back": "x++ dipakai dulu baru naik · ++x naik dulu baru dipakai"}, {"id": "P03-C004", "p": "P03", "tag": "relasi", "front": "= vs ==", "back": "= memberi nilai · == membandingkan"}, {"id": "P03-C005", "p": "P03", "tag": "ternary", "front": "Ternary", "back": "kondisi ? nilaiJikaTrue : nilaiJikaFalse"}, {"id": "P04-C001", "p": "P04", "tag": "elseif", "front": "if - else if - else", "back": "Diperiksa dari atas; cabang pertama yang true dijalankan, sisanya dilewati."}, {"id": "P05-C001", "p": "P05", "tag": "break", "front": "switch tanpa break", "back": "Fall-through: lanjut menjalankan case di bawahnya sampai bertemu break."}, {"id": "P05-C002", "p": "P05", "tag": "switch", "front": "switch vs if", "back": "switch untuk nilai pasti (1,2,'A') · if untuk rentang (nilai > 80)"}, {"id": "P06-C001", "p": "P06", "tag": "for", "front": "Cara kerja for", "back": "Inisialisasi (sekali) → cek kondisi → blok → step → cek lagi"}, {"id": "P07-C001", "p": "P07", "tag": "dowhile", "front": "while vs do-while", "back": "while: cek dulu (bisa 0 kali) · do-while: jalan dulu (min. 1 kali)"}, {"id": "P07-C002", "p": "P07", "tag": "nested", "front": "Loop bersarang", "back": "Total eksekusi = putaran luar × putaran dalam"}, {"id": "P09-C001", "p": "P09", "tag": "indeks", "front": "Indeks array", "back": "int a[n] → indeks 0 sampai n-1; a[n] di luar batas"}, {"id": "P09-C002", "p": "P09", "tag": "konsep", "front": "Ukuran array", "back": "byte = ukuran tipe × jumlah elemen"}, {"id": "P10-C001", "p": "P10", "tag": "akses", "front": "Akses member struct", "back": "namaObject.namaMember, mis. p.harga · array: mhs[2].nim"}, {"id": "P11-C001", "p": "P11", "tag": "konsep", "front": "Manfaat fungsi", "back": "Readability (struktur jelas) & reusability (dipakai ulang)"}, {"id": "P11-C002", "p": "P11", "tag": "pustaka", "front": "Fungsi pustaka penting", "back": "sqrt, pow (math) · strlen, strcpy, strcat (string) · toupper, tolower, isdigit (ctype)"}, {"id": "P12-C001", "p": "P12", "tag": "referensi", "front": "By value vs by reference", "back": "Value: salinan, asli tidak berubah · Reference (int &x): asli ikut berubah"}, {"id": "P12-C002", "p": "P12", "tag": "rekursif", "front": "Rekursif", "back": "Fungsi memanggil dirinya sendiri + wajib base case."}, {"id": "P13-C001", "p": "P13", "tag": "selection", "front": "Selection sort", "back": "Pilih minimum dari bagian belum urut → tukar ke depan bagian itu."}, {"id": "P13-C002", "p": "P13", "tag": "bubble", "front": "Bubble sort", "back": "Bandingkan pasangan bersebelahan, tukar bila salah; terbesar ke belakang tiap putaran."}, {"id": "P13-C003", "p": "P13", "tag": "konsep", "front": "FPB Euclid", "back": "while n ≠ 0: r = m mod n; m = n; n = r → hasil m"}, {"id": "P14-C001", "p": "P14", "tag": "konsep", "front": "Sequential search", "back": "Bandingkan K dengan A[0], A[1], … berhenti saat cocok; tidak ketemu → -1"}, {"id": "P15-C001", "p": "P15", "tag": "sentinel", "front": "Sentinel", "back": "A[n] ← K agar loop pasti berhenti; i == n berarti tidak ditemukan."}]});
